#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    Bool,
    SignedInt,
    UnsignedInt,
    Float,
    Complex,
    Object,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct DType {
    pub kind: Kind,
    pub precedence: u8,
}

impl DType {
    /// Returns the kind character representing the dtype kind,
    /// For convenience if needed (not strictly required here).
    pub fn kind_char(&self) -> char {
        match self.kind {
            Kind::Bool => 'b',
            Kind::SignedInt => 'i',
            Kind::UnsignedInt => 'u',
            Kind::Float => 'f',
            Kind::Complex => 'c',
            Kind::Object => 'O',
        }
    }
}

/// Task 1
/// Given a non-empty collection of dtypes, return a dtype that appears in
/// the collection and whose precedence is at least as large as that of every dtype in the collection.
pub fn find_max_precedence_type(types: Vec<DType>) -> DType {
    assert!(!types.is_empty(), "Input types collection must be non-empty");

    // Find the dtype with the max precedence, tie-breaking arbitrarily by first found
    let mut max_type = types[0];
    for dt in &types[1..] {
        if dt.precedence > max_type.precedence {
            max_type = *dt;
        }
    }
    max_type
}

/// Task 2
/// Given two collections: array_types and scalar_types,
/// determine the common dtype according to the rules:
///
/// - If only array_types is non-empty, return max precedence dtype from array_types.
/// - If only scalar_types is non-empty, return max precedence dtype from scalar_types.
/// - If both non-empty:
///    * find max from each,
///    * if kinds are equal, return max array dtype,
///    * else return max scalar dtype.
///
/// Return None if both collections are empty.
pub fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    let array_max = if array_types.is_empty() {
        None
    } else {
        Some(find_max_precedence_type(array_types))
    };

    let scalar_max = if scalar_types.is_empty() {
        None
    } else {
        Some(find_max_precedence_type(scalar_types))
    };

    match (array_max, scalar_max) {
        (Some(a), None) => Some(a),
        (None, Some(s)) => Some(s),
        (Some(a), Some(s)) => {
            if a.kind == s.kind {
                Some(a)
            } else {
                Some(s)
            }
        }
        (None, None) => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn dt(kind: Kind, precedence: u8) -> DType {
        DType { kind, precedence }
    }

    #[test]
    fn test_find_max_precedence_type() {
        let types = vec![
            dt(Kind::Bool, 0),
            dt(Kind::SignedInt, 3),
            dt(Kind::UnsignedInt, 5),
            dt(Kind::Float, 9),
            dt(Kind::Object, 13),
            dt(Kind::Complex, 11),
        ];
        let max_type = find_max_precedence_type(types);
        assert_eq!(max_type.precedence, 13);
        assert_eq!(max_type.kind, Kind::Object);
    }

    #[test]
    fn test_find_common_type_only_array() {
        let array_types = vec![
            dt(Kind::Bool, 0),
            dt(Kind::SignedInt, 2),
            dt(Kind::Float, 10),
        ];
        let scalar_types = vec![];
        let common = find_common_type(array_types, scalar_types).unwrap();
        assert_eq!(common.precedence, 10);
        assert_eq!(common.kind, Kind::Float);
    }

    #[test]
    fn test_find_common_type_only_scalar() {
        let array_types = vec![];
        let scalar_types = vec![
            dt(Kind::UnsignedInt, 7),
            dt(Kind::Complex, 11),
        ];
        let common = find_common_type(array_types, scalar_types).unwrap();
        assert_eq!(common.precedence, 11);
        assert_eq!(common.kind, Kind::Complex);
    }

    #[test]
    fn test_find_common_type_both_same_kind() {
        let array_types = vec![
            dt(Kind::SignedInt, 2),
            dt(Kind::SignedInt, 4),
        ];
        let scalar_types = vec![
            dt(Kind::SignedInt, 3),
        ];
        // max array: precedence 4, kind signed int
        // max scalar: precedence 3, kind signed int
        // kinds equal -> result is max array
        let common = find_common_type(array_types, scalar_types).unwrap();
        assert_eq!(common.precedence, 4);
        assert_eq!(common.kind, Kind::SignedInt);
    }

    #[test]
    fn test_find_common_type_both_different_kind() {
        let array_types = vec![
            dt(Kind::Float, 10),
        ];
        let scalar_types = vec![
            dt(Kind::Complex, 11),
        ];
        // kinds differ (float vs complex), so result is scalar max
        let common = find_common_type(array_types, scalar_types).unwrap();
        assert_eq!(common.precedence, 11);
        assert_eq!(common.kind, Kind::Complex);
    }

    #[test]
    fn test_find_common_type_empty_both() {
        let common = find_common_type(vec![], vec![]);
        assert!(common.is_none());
    }
}